<!doctype html><html><head><meta charset="utf-8"><title>Great Wave - low poly</title>
<style>html,body{margin:0;height:100%;overflow:hidden;background:#e9dcbf}canvas{display:block}</style>
<script type="importmap">{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js"}}</script>
</head><body><script type="module">
import * as THREE from 'three';
const PAPER=0xe9dcbf,PRUSSIAN=0x1c3a6b,DEEP=0x0f2347,MID=0x5d86b0,FOAM=0xf3ecd9,HULL=0xd9a97a,SKYGREY=0x8a8478;
const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));
document.body.appendChild(renderer.domElement);
const scene=new THREE.Scene();
// Paper sky: beige top fading to the print's grey horizon band behind Fuji
const skyCanvas=document.createElement('canvas');skyCanvas.width=2;skyCanvas.height=256;
const g=skyCanvas.getContext('2d'),gr=g.createLinearGradient(0,0,0,256);
gr.addColorStop(0,'#e3cfa6');gr.addColorStop(0.55,'#ece2c9');gr.addColorStop(0.8,'#9b958a');gr.addColorStop(1,'#6f6a62');
g.fillStyle=gr;g.fillRect(0,0,2,256);scene.background=new THREE.CanvasTexture(skyCanvas);
const camera=new THREE.PerspectiveCamera(35,1,0.1,200);camera.position.set(0,3,30);camera.lookAt(0,3,0);
scene.add(new THREE.HemisphereLight(0xfff6e0,0x334466,1.6));
const sun=new THREE.DirectionalLight(0xffffff,1.6);sun.position.set(-5,10,10);scene.add(sun);
const mat=c=>new THREE.MeshLambertMaterial({color:c,flatShading:true,side:THREE.DoubleSide});
// Low poly clouds (flat paper-white blobs, upper right like the print)
for(const [x,y,s] of [[4,11,2.2],[7,10.4,1.8],[10,11.2,2],[13,9.8,1.6]]){const c=new THREE.Mesh(new THREE.IcosahedronGeometry(s,0),mat(0xf2ead6));c.position.set(x,y,-20);c.scale.y=0.45;scene.add(c);}
// Mount Fuji, small and central, framed by the trough
const fuji=new THREE.Group();
const fb=new THREE.Mesh(new THREE.ConeGeometry(2.2,1.6,9,1),mat(0x3d4f6a));fuji.add(fb);
const fc=new THREE.Mesh(new THREE.ConeGeometry(1.15,0.85,9,1),mat(0xf6f1e4));fc.position.y=0.4;fuji.add(fc);
fuji.position.set(1.5,0.6,-8);scene.add(fuji);
// Wave sheet: a ribbon swept along a 2D profile, extruded in depth
function waveMesh(profile,depth,color,z){const s=new THREE.Shape(profile.map(p=>new THREE.Vector2(p[0],p[1])));
 const geo=new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false,curveSegments:3});const m=new THREE.Mesh(geo,mat(color));m.position.z=z;scene.add(m);return m;}
// Great wave: rises from left, curls over to the right like a claw
const big=[];const curl=[];
for(let i=0;i<=24;i++){const t=i/24,a=Math.PI*1.1*t;big.push([-14+t*9+Math.sin(a)*2.5,-1+Math.sin(t*Math.PI*0.9)*12]);}
const outer=[[-16,-3],[-16,4],...big,[-3.6,7.5],[-4.2,6],[-5.5,5.2],[-6.6,2.5],[-6,-0.5],[-3,-3]];
const wave1=waveMesh(outer,3,PRUSSIAN,-2);
const inner=outer.map(([x,y])=>[x*0.93-0.6,y*0.86-0.3]);waveMesh(inner,0.2,DEEP,1.05);
// Foam rim: white crest claws along the lip
const claws=new THREE.Group();scene.add(claws);
for(let i=6;i<big.length;i++){const [x,y]=big[i];const c=new THREE.Mesh(new THREE.ConeGeometry(0.45,1.2,4),mat(FOAM));
 c.position.set(x+0.3,y+0.2,1.2);c.rotation.z=-0.6-i*0.08;claws.add(c);
 const c2=c.clone();c2.position.set(x-0.4,y-0.6,1.25);c2.scale.setScalar(0.6);claws.add(c2);}
for(let i=0;i<14;i++){const c=new THREE.Mesh(new THREE.ConeGeometry(0.35,0.9,4),mat(FOAM));c.position.set(-3.5-i*0.15+Math.sin(i)*0.6,7.6-i*0.55,1.3);c.rotation.z=-2.4+Math.sin(i*1.7)*0.4;claws.add(c);}
// Spray dots falling from the curl
const spray=new THREE.Group();scene.add(spray);
for(let i=0;i<40;i++){const d=new THREE.Mesh(new THREE.TetrahedronGeometry(0.09),mat(FOAM));d.position.set(-4+Math.random()*4,1+Math.random()*6,1.5);d.userData.v=0.3+Math.random()*0.5;spray.add(d);}
// Foreground small wave (the "mini Fuji" wave) bottom left, plus right-side swell
const fg=waveMesh([[-16,-6],[-16,-1],[-12,1.5],[-9,3.2],[-7,1.5],[-5,-1],[-2,-3],[2,-6]],2,PRUSSIAN,3);
const fgCap=new THREE.Mesh(new THREE.ConeGeometry(1.2,1,6),mat(FOAM));fgCap
